// Server-safe translator: resolve a `t()` for any locale string (falls back to
// English for unknown locales/keys). Lets Server Components translate without
// the React context — pass a locale read from the user's saved preference.
export function getT(locale: string) {
  const dict = (translations as Record<string, Record<TranslationKey, string>>)[locale] ?? translations.en
  return (key: TranslationKey) => dict[key] ?? translations.en[key] ?? key
}

